'use strict';
const projectFormats={landscape:{name:'Landscape · 16:9',width:960,height:540},portrait:{name:'Vertical · 9:16',width:303.75,height:540},square:{name:'Square · 1:1',width:540,height:540}};
function projectView(p=project){const f=projectFormats[p.canvasFormat]||projectFormats.landscape;return{...f,left:(960-f.width)/2,top:0}}
function exportGeometry(resolution,p=project){const size=Math.round(Number(resolution)*9/16),format=p.canvasFormat||'landscape';const width=format==='portrait'||format==='square'?size:Number(resolution),height=format==='square'?size:format==='portrait'?Number(resolution):size;return{width,height,renderWidth:Math.round(height*16/9),renderHeight:height}}
const formatFrame=document.createElement('div');formatFrame.className='format-frame';$('stage').before(formatFrame);formatFrame.append($('stage'));
function layoutProjectFormat(){const paper=document.querySelector('.paperstage'),style=getComputedStyle(paper),width=paper.clientWidth-parseFloat(style.paddingLeft)-parseFloat(style.paddingRight),height=paper.clientHeight-parseFloat(style.paddingTop)-parseFloat(style.paddingBottom),view=projectView(),h=Math.max(1,Math.min(height,width*view.height/view.width)),w=h*view.width/view.height;formatFrame.style.width=w+'px';formatFrame.style.height=h+'px';const stage=$('stage');stage.style.width=h*16/9+'px';stage.style.height=h+'px';stage.style.maxWidth='none';stage.style.maxHeight='none';document.querySelector('.stage-actions span').textContent=view.name}
new ResizeObserver(layoutProjectFormat).observe(document.querySelector('.paperstage'));
$('sceneTab').insertAdjacentHTML('afterbegin','<section class="project-format-tools"><h3>Canvas format</h3><select id="projectFormat" aria-label="Project canvas format"><option value="landscape">Landscape · 16:9</option><option value="portrait">Vertical · 9:16</option><option value="square">Square · 1:1</option></select><button id="fitSceneFormat">Fit scene content</button><p class="note">Format applies to every scene. Reposition content inside the frame or use Fit scene content.</p></section>');
$('projectFormat').onchange=e=>{if(recording)return;stop();project.canvasFormat=e.target.value;save();render();layoutProjectFormat()};
$('fitSceneFormat').onclick=()=>{const list=current().objects.filter(o=>!o.hidden);if(!list.length)return;if(list.some(o=>o.locked))return toast('Unlock the scene layers before fitting them.');const box=selectionBounds(list),view=projectView(),scale=Math.min(1,(view.width-24)/Math.max(1,box.w),(view.height-24)/Math.max(1,box.h)),items=capturedLayers(list);applyCapturedTransform(items,{scale,anchor:{x:box.cx,y:box.cy},translate:{x:480-box.cx,y:270-box.cy}});save();render()};
let formatCapture=null;
function prepareFormatCapture(){const geometry=exportGeometry($('resolution').value);if((project.canvasFormat||'landscape')==='landscape'){formatCapture=null;return $('stage')}const canvas=document.createElement('canvas');canvas.width=geometry.width;canvas.height=geometry.height;formatCapture={canvas,view:projectView()};updateFormatCapture();return canvas}
function updateFormatCapture(){if(!formatCapture)return;const{canvas,view}=formatCapture,stage=$('stage'),c=canvas.getContext('2d');c.clearRect(0,0,canvas.width,canvas.height);c.drawImage(stage,view.left/960*stage.width,0,view.width/960*stage.width,stage.height,0,0,canvas.width,canvas.height)}
function releaseFormatCapture(){formatCapture=null}
const drawBeforeFormat=draw;draw=function(){drawBeforeFormat();updateFormatCapture()};
const controlsBeforeFormat=renderControls;renderControls=function(){controlsBeforeFormat();const o=object();if(o?.type==='video')for(const[id,fit]of[['fitVideo',Math.min],['fillVideo',Math.max]])$(id).onclick=()=>{const crop=cropRect(o),view=projectView();setDisplayedFields(o,{x:480,y:270,scale:fit(view.width/(o.width*crop.w),view.height/(o.height*crop.h))});render()}};
const extrasBeforeFormat=renderExtras;renderExtras=function(){extrasBeforeFormat();$('projectFormat').value=project.canvasFormat||'landscape';for(const option of $('resolution').options){const d=exportGeometry(option.value);option.textContent=d.width+' × '+d.height+(option.value==='960'?' · draft':option.value==='1920'?' · HD':' · high resolution')}layoutProjectFormat()};
const captionBeforeFormats=drawCaptions;drawCaptions=function(c,s,t){if((project.canvasFormat||'landscape')==='landscape')return captionBeforeFormats(c,s,t);const active=(s.captions||[]).filter(x=>t>=x.start&&t<x.end);if(!active.length)return;const view=projectView(),style=s.captionStyle||{},size=style.size||25,padding=14,max=view.width-padding*2-16;c.save();c.font='600 '+size+'px Arial';c.textBaseline='middle';const tokens=[];for(const caption of active){const words=caption.text.trim().split(/\s+/);for(let i=0;i<words.length;i++){const w=caption.words?.[i],start=w?.start??caption.start+i/words.length*(caption.end-caption.start),end=w?.end??caption.start+(i+1)/words.length*(caption.end-caption.start);for(const part of splitCaptionWord(c,words[i],max))tokens.push({text:part,width:c.measureText(part+' ').width,active:t>=start&&t<end})}}const rows=[[]];let width=0;for(const token of tokens){if(width+token.width>max&&rows.at(-1).length){rows.push([]);width=0}rows.at(-1).push(token);width+=token.width}const shown=rows.slice(0,5),height=shown.length*(size+9)+16,top=style.position==='top'?25:style.position==='center'?270-height/2:520-height;rect(c,view.left+padding,top,view.width-padding*2,height,'rgba(12,15,20,.88)',7);shown.forEach((row,i)=>{let x=480-row.reduce((sum,w)=>sum+w.width,0)/2;const y=top+8+(i+.5)*(size+9);for(const token of row){const highlighted=style.mode==='highlight'&&token.active;if(highlighted)rect(c,x-2,y-size/2-3,token.width,size+6,style.highlight||'#e5b75d',3);c.fillStyle=highlighted?'#15171c':'#fffaf0';c.textAlign='left';c.fillText(token.text,x,y);x+=token.width}});c.restore()};
function splitCaptionWord(c,text,max){const result=[];let part='';for(const char of text){if(part&&c.measureText(part+char+' ').width>max){result.push(part);part=''}part+=char}if(part)result.push(part);return result}
const thumbnailBeforeFormats=renderStoryThumbnail;renderStoryThumbnail=async function(canvas,s){if((project.canvasFormat||'landscape')==='landscape')return thumbnailBeforeFormats(canvas,s);const scratch=document.createElement('canvas');scratch.width=384;scratch.height=216;document.body.append(scratch);scratch.hidden=true;try{await thumbnailBeforeFormats(scratch,s);if(!canvas.isConnected)return;const view=projectView(),c=canvas.getContext('2d'),height=canvas.height,width=height*view.width/view.height;c.fillStyle='#11131a';c.fillRect(0,0,canvas.width,canvas.height);c.drawImage(scratch,view.left/960*scratch.width,0,view.width/960*scratch.width,scratch.height,(canvas.width-width)/2,0,width,height)}finally{scratch.remove()}};
const formatValidator=valid;valid=function(p){return formatValidator(p)&&(p.canvasFormat===undefined||Object.hasOwn(projectFormats,p.canvasFormat))};
render();layoutProjectFormat();
